from approved_merge_539 import normalize
from test_sync_crash_capture import restore_sync_crash_capture
from pathlib import Path
import unittest,hashlib
ROOT=Path(__file__).resolve().parents[2]
class GoalsUploadFixtureTests(unittest.TestCase):
    def test_only_upload_fixture_changes(self):
        s=restore_sync_crash_capture(normalize('source:AteTests/UserDataSyncTests.swift', (ROOT/"AteTests/UserDataSyncTests.swift").read_text()))
        self.assertEqual(s.count('    func testGoalsChangeDuringUploadRefusesCommit() async throws {\n        let remoteGoals = SyncRecord(user_id: "u1", kind: "goals", id: "current",\n                                     data: AnyJSON(try JSONEncoder().encode(\n                                        DailyNutritionGoals(energyKcal: 2100, proteinGrams: nil,\n                                                            carbohydratesGrams: nil, fatGrams: nil,\n                                                            fibreGrams: nil))),\n                                     stampMs: 2_000_000, deleted: false)\n        let transport = transportWith(rows: [remoteGoals])\n        let store = try makeStore(transport: transport)\n        // A remote-only goals pull has no upload and cannot trigger onPush.\n        // Seed another family so this fixture really exercises an in-flight edit.\n        let context = ModelContext(store.journalStore.container!)\n        let local = Ate.JournalEntry(id: "j-upload-trigger", createdAt: Date(timeIntervalSince1970: 1000),\n                                     prompt: "", text: "local upload", state: nil, recipeIDs: [])\n        local.kindRaw = JournalEntryKind.reflection.rawValue\n        context.insert(local)\n        try context.save()\n        var hookRan = false\n        transport.onPush = { _ in\n            hookRan = true\n            try! store.journalGoalsRepository.save(\n                DailyNutritionGoals(energyKcal: 1800, proteinGrams: nil, carbohydratesGrams: nil,\n                                    fatGrams: nil, fibreGrams: nil))\n        }\n\n        await store.syncUserDataFamilies()\n\n        XCTAssertEqual(transport.pushAttempts, 1, "The fixture must perform a real upload")\n        XCTAssertTrue(hookRan, "The local goals edit must actually happen during that upload")\n        XCTAssertEqual(try store.journalGoalsRepository.load().energyKcal, 1800,\n                       "the mid-upload goals change stands; the remote winner must not overwrite it")\n        XCTAssertNil(store.meta.goalsStamps)\n    }\n'),1)
        s=s.replace('    func testGoalsChangeDuringUploadRefusesCommit() async throws {\n        let remoteGoals = SyncRecord(user_id: "u1", kind: "goals", id: "current",\n                                     data: AnyJSON(try JSONEncoder().encode(\n                                        DailyNutritionGoals(energyKcal: 2100, proteinGrams: nil,\n                                                            carbohydratesGrams: nil, fatGrams: nil,\n                                                            fibreGrams: nil))),\n                                     stampMs: 2_000_000, deleted: false)\n        let transport = transportWith(rows: [remoteGoals])\n        let store = try makeStore(transport: transport)\n        // A remote-only goals pull has no upload and cannot trigger onPush.\n        // Seed another family so this fixture really exercises an in-flight edit.\n        let context = ModelContext(store.journalStore.container!)\n        let local = Ate.JournalEntry(id: "j-upload-trigger", createdAt: Date(timeIntervalSince1970: 1000),\n                                     prompt: "", text: "local upload", state: nil, recipeIDs: [])\n        local.kindRaw = JournalEntryKind.reflection.rawValue\n        context.insert(local)\n        try context.save()\n        var hookRan = false\n        transport.onPush = { _ in\n            hookRan = true\n            try! store.journalGoalsRepository.save(\n                DailyNutritionGoals(energyKcal: 1800, proteinGrams: nil, carbohydratesGrams: nil,\n                                    fatGrams: nil, fibreGrams: nil))\n        }\n\n        await store.syncUserDataFamilies()\n\n        XCTAssertEqual(transport.pushAttempts, 1, "The fixture must perform a real upload")\n        XCTAssertTrue(hookRan, "The local goals edit must actually happen during that upload")\n        XCTAssertEqual(try store.journalGoalsRepository.load().energyKcal, 1800,\n                       "the mid-upload goals change stands; the remote winner must not overwrite it")\n        XCTAssertNil(store.meta.goalsStamps)\n    }\n','    func testGoalsChangeDuringUploadRefusesCommit() async throws {\n        let remoteGoals = SyncRecord(user_id: "u1", kind: "goals", id: "current",\n                                     data: AnyJSON(try JSONEncoder().encode(\n                                        DailyNutritionGoals(energyKcal: 2100, proteinGrams: nil,\n                                                            carbohydratesGrams: nil, fatGrams: nil,\n                                                            fibreGrams: nil))),\n                                     stampMs: 2_000_000, deleted: false)\n        let transport = transportWith(rows: [remoteGoals])\n        let store = try makeStore(transport: transport)\n        transport.onPush = { _ in\n            try! store.journalGoalsRepository.save(\n                DailyNutritionGoals(energyKcal: 1800, proteinGrams: nil, carbohydratesGrams: nil,\n                                    fatGrams: nil, fibreGrams: nil))\n        }\n\n        await store.syncUserDataFamilies()\n\n        XCTAssertEqual(try store.journalGoalsRepository.load().energyKcal, 1800,\n                       "the mid-upload goals change stands; the remote winner must not overwrite it")\n        XCTAssertNil(store.meta.goalsStamps)\n    }\n',1)
        self.assertEqual(hashlib.sha256(s.encode()).hexdigest(),'05dd1f71cbbeee92b909878db1d02476518ee80587fef0d2a2f54a3f999003e4')

